using System;
using Customization;

public class UomRollbackV3 : CustomizationPlugin
{
    public override void UpdateDatabase()
    {
        WriteLog("=== UomRollbackV3: Reversing YDS→PIECE + BOLTID→PIECENBR ===");

        var cs = System.Configuration.ConfigurationManager.ConnectionStrings["ProjectX"];
        if (cs == null) { WriteLog("ERROR: No connection string."); return; }

        string connStr = cs.ConnectionString + ";TrustServerCertificate=True";
        using (var conn = new Microsoft.Data.SqlClient.SqlConnection(connStr))
        {
            conn.Open();

            // Pre-flight: check if rollback is needed
            int ydsCount = 0;
            using (var cmd = conn.CreateCommand())
            {
                cmd.CommandText = "SELECT COUNT(*) FROM InventoryItem WHERE BaseUnit = 'YDS'";
                cmd.CommandTimeout = 30;
                ydsCount = (int)cmd.ExecuteScalar();
            }
            WriteLog($"Pre-flight: {ydsCount} items with BaseUnit=YDS");
            if (ydsCount == 0)
            {
                WriteLog("No items with BaseUnit=YDS. Nothing to rollback.");
                return;
            }

            using (var txn = conn.BeginTransaction())
            {
                try
                {
                    int total = 0;

                    // Reverse: BaseUnit/SalesUnit YDS→PIECE
                    WriteLog("--- Reversing BaseUnit/SalesUnit ---");
                    total += Exec(conn, txn, "UPDATE InventoryItem SET BaseUnit = 'PIECE' WHERE BaseUnit = 'YDS'", "InventoryItem.BaseUnit");
                    total += Exec(conn, txn, "UPDATE InventoryItem SET SalesUnit = 'PIECE' WHERE SalesUnit = 'YDS' AND PurchaseUnit = 'YDS'", "InventoryItem.SalesUnit");
                    total += Safe(conn, txn, "UPDATE INItemClass SET BaseUnit = 'PIECE' WHERE BaseUnit = 'YDS'", "INItemClass.BaseUnit");
                    total += Safe(conn, txn, "UPDATE INItemClass SET SalesUnit = 'PIECE' WHERE SalesUnit = 'YDS'", "INItemClass.SalesUnit");

                    // Reverse: Transaction UOM YDS→PIECE
                    WriteLog("--- Reversing transaction UOM ---");
                    total += Safe(conn, txn, "UPDATE INTran SET UOM = 'PIECE' WHERE UOM = 'YDS'", "INTran.UOM");
                    total += Safe(conn, txn, "UPDATE INTranSplit SET UOM = 'PIECE' WHERE UOM = 'YDS'", "INTranSplit.UOM");
                    total += Safe(conn, txn, "UPDATE SOLine SET UOM = 'PIECE' WHERE UOM = 'YDS'", "SOLine.UOM");
                    total += Safe(conn, txn, "UPDATE SOLineSplit SET UOM = 'PIECE' WHERE UOM = 'YDS'", "SOLineSplit.UOM");
                    total += Safe(conn, txn, "UPDATE SOShipLine SET UOM = 'PIECE' WHERE UOM = 'YDS'", "SOShipLine.UOM");
                    total += Safe(conn, txn, "UPDATE SOShipLineSplit SET UOM = 'PIECE' WHERE UOM = 'YDS'", "SOShipLineSplit.UOM");
                    total += Safe(conn, txn, "UPDATE POLine SET UOM = 'PIECE' WHERE UOM = 'YDS'", "POLine.UOM");
                    total += Safe(conn, txn, "UPDATE POLineSplit SET UOM = 'PIECE' WHERE UOM = 'YDS'", "POLineSplit.UOM");
                    total += Safe(conn, txn, "UPDATE POReceiptLine SET UOM = 'PIECE' WHERE UOM = 'YDS'", "POReceiptLine.UOM");
                    total += Safe(conn, txn, "UPDATE POReceiptLineSplit SET UOM = 'PIECE' WHERE UOM = 'YDS'", "POReceiptLineSplit.UOM");
                    total += Safe(conn, txn, "UPDATE ARTran SET UOM = 'PIECE' WHERE UOM = 'YDS'", "ARTran.UOM");
                    total += Safe(conn, txn, "UPDATE APTran SET UOM = 'PIECE' WHERE UOM = 'YDS'", "APTran.UOM");
                    total += Safe(conn, txn, "UPDATE ARSalesPrice SET UOM = 'PIECE' WHERE UOM = 'YDS'", "ARSalesPrice.UOM");
                    total += Safe(conn, txn, "UPDATE APVendorPrice SET UOM = 'PIECE' WHERE UOM = 'YDS'", "APVendorPrice.UOM");
                    total += Safe(conn, txn, "UPDATE INPIDetail SET UOM = 'PIECE' WHERE UOM = 'YDS'", "INPIDetail.UOM");
                    total += Safe(conn, txn, "UPDATE INItemPlan SET UOM = 'PIECE' WHERE UOM = 'YDS'", "INItemPlan.UOM");

                    // Reverse: LotSerClass BOLTID→PIECENBR
                    WriteLog("--- Reversing LotSerClass ---");
                    total += Safe(conn, txn, "UPDATE InventoryItem SET LotSerClassID = 'PIECENBR' WHERE LotSerClassID = 'BOLTID'", "InventoryItem.LotSerClassID");
                    total += Safe(conn, txn, "UPDATE INItemClass SET LotSerClassID = 'PIECENBR' WHERE LotSerClassID = 'BOLTID'", "INItemClass.LotSerClassID");
                    total += Safe(conn, txn, "UPDATE INLotSerClassSegment SET LotSerClassID = 'PIECENBR' WHERE LotSerClassID = 'BOLTID'", "INLotSerClassSegment.LotSerClassID");
                    total += Safe(conn, txn, "UPDATE INLotSerClass SET LotSerClassID = 'PIECENBR' WHERE LotSerClassID = 'BOLTID'", "INLotSerClass.LotSerClassID");

                    txn.Commit();
                    WriteLog($"=== ROLLBACK COMMITTED. {total} rows reverted. ===");
                }
                catch (Exception ex)
                {
                    WriteLog($"!!! ROLLBACK FAILED: {ex.Message}");
                    try { txn.Rollback(); } catch { }
                    throw;
                }
            }
        }
    }

    private int Exec(Microsoft.Data.SqlClient.SqlConnection c, Microsoft.Data.SqlClient.SqlTransaction t, string sql, string l)
    {
        using (var cmd = c.CreateCommand()) { cmd.Transaction = t; cmd.CommandText = sql; cmd.CommandTimeout = 300; int r = cmd.ExecuteNonQuery(); WriteLog($"  {l}: {r} rows"); return r; }
    }

    private int Safe(Microsoft.Data.SqlClient.SqlConnection c, Microsoft.Data.SqlClient.SqlTransaction t, string sql, string l)
    {
        try { return Exec(c, t, sql, l); } catch (Microsoft.Data.SqlClient.SqlException ex) when (ex.Number == 207 || ex.Number == 208) { WriteLog($"  {l}: SKIPPED"); return 0; }
    }
}
